public interface org.springframework.data.jpa.repository
        .JpaSpecificationExecutor<T> {
  java.util.Optional<T> findOne(Specification<T>);
  java.util.List<T> findAll(Specification<T>);
  org.springframework.data.domain.Page<T> findAll(Specification<T>,
          org.springframework.data.domain.Pageable);
  long count(Specification<T>);
  boolean exists(Specification<T>);
}

