-- 개수 쿼리에서 조인을 뗀다

public static Specification<Member> teamNameEqSmart(String teamName) {
    return (root, query, cb) -> {
        if (Long.class != query.getResultType()) {   // 개수 쿼리가 아니면
            root.fetch("team", JoinType.LEFT);
        }
        Join<Member, Team> team = root.join("team");
        return cb.equal(team.get("name"), teamName);
    };
}

@Test
@Transactional
void 개수_최적화() {
    em.clear();
    memberRepository.findAll(
            Specification.where(MemberSpec.teamNameEqSmart("teamA")),
            PageRequest.of(0, 3));
}

